import teamMemberSchema from "@tepian-k3/schema/platform/team-member.schema";
import {
  createTRPCRouter,
  formDataInput,
  formDataProcedure,
  withPermission,
  withRateLimit,
} from "../..";
import teamMemberQueries from "@tepian-k3/queries/platform/team-member.queries";
import z from "zod";
import { TRPCError } from "@trpc/server";
import { runEffect } from "../../utils/run-effect";
import { rateLimiters } from "@tepian-k3/services/rate-limiter";
import { CACHE_KEYS, CACHE_TTL } from "@tepian-k3/constants";
import { withCache, withCacheInvalidation } from "../../utils/cache-helper";
import { Effect } from "effect";
import { processAndUploadImageIfPresent } from "../../utils/image-upload";

export const teamMemberRouter = createTRPCRouter({
  getAllTeamMembers: withRateLimit(rateLimiters.moderate()).query(
    async ({ ctx }) =>
      await withCache(
        CACHE_KEYS.TEAM_MEMBERS_ALL,
        CACHE_TTL.LONG,
        () => runEffect(teamMemberQueries.getAllActiveTeamMembers()),
        () => ctx.c.header("X-Data-Source", "cache"),
      ),
  ),

  getAllTeamMembersForAdmin: withPermission("banners.view").query(
    async () => await runEffect(teamMemberQueries.getAllTeamMembersForAdmin()),
  ),

  getPaginatedTeamMembers: withPermission("banners.view")
    .input(teamMemberSchema.getAllTeamMembersSchema)
    .query(async ({ input }) => {
      const { data, pageCount } = await runEffect(
        teamMemberQueries.getOffsetPaginatedTeamMembers(input),
      );

      return { data, pageCount };
    }),

  getTeamMemberById: withPermission("banners.view")
    .input(
      z.object({
        id: z.uuidv7(),
      }),
    )
    .query(async ({ input }) => {
      const member = await runEffect(
        teamMemberQueries.getTeamMemberById(input.id),
      );

      if (!member) {
        throw new TRPCError({
          code: "NOT_FOUND",
          message: "Anggota tim tidak ditemukan",
        });
      }

      return member;
    }),

  createTeamMember: withPermission("banners.create")
    .input(formDataInput)
    .use(formDataProcedure(teamMemberSchema.createTeamMemberSchema))
    .mutation(
      async ({ ctx }) =>
        await withCacheInvalidation(CACHE_KEYS.TEAM_MEMBERS_PREFIX, () =>
          runEffect(
            Effect.gen(function* () {
              const photoKey = yield* processAndUploadImageIfPresent(
                ctx.input.data.photo,
                { folder: "team-members" },
              );

              const result = yield* teamMemberQueries.createTeamMember(
                ctx.input.data,
                photoKey,
              );

              return result;
            }),
          ),
        ),
    ),

  updateTeamMember: withPermission("banners.update")
    .input(formDataInput)
    .use(formDataProcedure(teamMemberSchema.updateTeamMemberSchema))
    .mutation(
      async ({ ctx }) =>
        await withCacheInvalidation(CACHE_KEYS.TEAM_MEMBERS_PREFIX, () =>
          runEffect(
            Effect.gen(function* () {
              const photoKey = yield* processAndUploadImageIfPresent(
                ctx.input.data.photo,
                { folder: "team-members" },
              );

              const result = yield* teamMemberQueries.updateTeamMember(
                ctx.input.data,
                photoKey,
              );

              return result;
            }),
          ),
        ),
    ),

  deleteTeamMember: withPermission("banners.delete")
    .input(
      z.object({
        id: z.uuidv7(),
      }),
    )
    .mutation(
      async ({ input }) =>
        await withCacheInvalidation(CACHE_KEYS.TEAM_MEMBERS_PREFIX, () =>
          runEffect(teamMemberQueries.deleteTeamMember(input.id)),
        ),
    ),

  restoreTeamMember: withPermission("banners.delete")
    .input(
      z.object({
        id: z.uuidv7(),
      }),
    )
    .mutation(
      async ({ input }) =>
        await withCacheInvalidation(CACHE_KEYS.TEAM_MEMBERS_PREFIX, () =>
          runEffect(teamMemberQueries.restoreTeamMember(input.id)),
        ),
    ),

  hardDeleteTeamMember: withPermission("banners.delete")
    .input(
      z.object({
        id: z.uuidv7(),
      }),
    )
    .mutation(
      async ({ input }) =>
        await withCacheInvalidation(CACHE_KEYS.TEAM_MEMBERS_PREFIX, () =>
          runEffect(teamMemberQueries.hardDeleteTeamMember(input.id)),
        ),
    ),

  reorderTeamMembers: withPermission("banners.update")
    .input(teamMemberSchema.reorderTeamMembersSchema)
    .mutation(
      async ({ input }) =>
        await withCacheInvalidation(CACHE_KEYS.TEAM_MEMBERS_PREFIX, () =>
          runEffect(teamMemberQueries.reorderTeamMembers(input.items)),
        ),
    ),
});

